SELECT sc.*, p.code_name AS parent_code_name FROM system_codes sc LEFT JOIN system_codes p ON sc.parent_code_id = p.code_id
sc.code_group = #{codeGroup}
AND sc.parent_code_id = #{parentCodeId}
AND sc.is_active = 1
ORDER BY sc.code_group, sc.sort_order, sc.code_id

SELECT sc.*, p.code_name AS parent_code_name FROM system_codes sc LEFT JOIN system_codes p ON sc.parent_code_id = p.code_id WHERE sc.parent_code_id = #{parentCodeId}
AND sc.is_active = 1
ORDER BY sc.sort_order, sc.code_id

SELECT * FROM system_codes
WHERE code_group = #{codeGroup} AND code_value = #{codeValue}
LIMIT 1

